window.ZK_PRED["15040"]={"meta": "分析范围：2023—2026 年共 4 套真题（选择 100 题 · 简答 20 题 · 论述 4 题）。该科开考时间短、样本小，预测以真题高频 + 教材专题为纲；展开的模拟题参考真题出题风格拟写。", "heat": [{"name": "新时代与中国式现代化", "n": 20, "n5": 20}, {"name": "五位一体·经济", "n": 7, "n5": 7}, {"name": "国家安全与强军", "n": 7, "n5": 7}, {"name": "五位一体·社会", "n": 4, "n5": 4}, {"name": "五位一体·政治", "n": 3, "n5": 3}, {"name": "五位一体·文化", "n": 3, "n5": 3}, {"name": "五位一体·生态", "n": 3, "n5": 3}, {"name": "开放与人类命运共同体", "n": 3, "n5": 3}, {"name": "党的建设", "n": 3, "n5": 3}, {"name": "四个全面", "n": 2, "n5": 2}, {"name": "党的全面领导", "n": 1, "n5": 1}], "groups": [{"title": "客观题 · 高频专题（4 套真题重复/必考）", "items": [{"tier": 3, "topic": "中国式现代化：内涵特征 / 本质要求 / 重大意义", "stat": "20 题 · 4 套全考 · 简答论述 5 次", "reason": "全科绝对核心，每一套卷必出 4-6 题，下轮继续是大头。", "q": [{"t": "单选", "q": "中国式现代化是人口规模巨大的现代化，其显著特征是", "o": ["A.全体人民共同富裕的现代化", "B.物质文明和精神文明相协调的现代化", "C.走和平发展道路的现代化", "D.人口规模巨大"], "a": "D"}, {"t": "单选", "q": "中国式现代化的本质要求，排在首位的是", "o": ["A.坚持中国共产党领导", "B.坚持中国特色社会主义", "C.实现高质量发展", "D.丰富人民精神世界"], "a": "A"}, {"t": "单选", "q": "中国式现代化与西方现代化的本质区别在于", "o": ["A.坚持中国共产党领导、坚持中国特色社会主义", "B.工业化水平", "C.城市化程度", "D.科技发展"], "a": "A"}]}, {"tier": 3, "topic": "高质量发展与新发展理念（新质生产力）", "stat": "7 题 · 4 套全考", "reason": "经济建设主线，2026.4 简答考“构建新发展格局”。", "q": [{"t": "单选", "q": "新发展理念包括", "o": ["A.创新、协调、绿色、开放、共享", "B.改革、开放、创新、协调、共享", "C.创新、协调、绿色、开放、共赢", "D.公平、效率、绿色、开放、共享"], "a": "A"}, {"t": "单选", "q": "新质生产力的核心要素是", "o": ["A.科技创新", "B.资本积累", "C.劳动力数量", "D.资源投入"], "a": "A"}, {"t": "单选", "q": "我国经济已由高速增长阶段转向", "o": ["A.高质量发展阶段", "B.平稳发展阶段", "C.低速增长阶段", "D.集约发展阶段"], "a": "A"}]}, {"tier": 3, "topic": "总体国家安全观（国家安全体系）", "stat": "7 题 · 4 套全考", "reason": "总体国家安全观是国家安全章核心，年年出。", "q": [{"t": "单选", "q": "总体国家安全观以____为宗旨", "o": ["A.人民安全", "B.政治安全", "C.经济安全", "D.军事安全"], "a": "A"}, {"t": "单选", "q": "总体国家安全观以____为根本", "o": ["A.政治安全", "B.人民安全", "C.经济安全", "D.文化安全"], "a": "A"}, {"t": "单选", "q": "坚持总体国家安全观，要统筹发展和", "o": ["A.安全", "B.改革", "C.开放", "D.稳定"], "a": "A"}]}, {"tier": 3, "topic": "全过程人民民主 + 根本政治制度", "stat": "政治类 3 题 + 高频", "reason": "人民当家作主制度体系，与“人大制度是根本政治制度”连考。", "q": [{"t": "单选", "q": "我国的根本政治制度是", "o": ["A.人民代表大会制度", "B.中国共产党领导的多党合作和政治协商制度", "C.民族区域自治制度", "D.基层群众自治制度"], "a": "A"}, {"t": "单选", "q": "全过程人民民主的本质是", "o": ["A.人民当家作主", "B.依法治国", "C.党的领导", "D.民主选举"], "a": "A"}, {"t": "单选", "q": "协商民主是我国社会主义民主政治的", "o": ["A.独特形式", "B.唯一形式", "C.补充形式", "D.过渡形式"], "a": "A"}]}, {"tier": 3, "topic": "中华文明特性与文化自信", "stat": "文化类 3 题 + 高频", "reason": "2026.4 简答考“中华文明的五个特性”，选择题同步高频。", "q": [{"t": "单选", "q": "中华文明的突出特性不包括", "o": ["A.连续性", "B.创新性", "C.封闭性", "D.和平性"], "a": "C"}, {"t": "单选", "q": "中华文明最突出的特性是", "o": ["A.连续性", "B.包容性", "C.统一性", "D.创新性"], "a": "A"}, {"t": "单选", "q": "文化自信是更基础、更广泛、更____的自信", "o": ["A.深厚", "B.重要", "C.根本", "D.持久"], "a": "A"}]}, {"tier": 3, "topic": "生态文明建设（绿水青山/双碳目标）", "stat": "生态类 3 题", "reason": "生态文明章稳定出题。", "q": [{"t": "单选", "q": "“绿水青山就是金山银山”体现的生态理念是", "o": ["A.人与自然和谐共生", "B.先发展后治理", "C.人类征服自然", "D.生态让步发展"], "a": "A"}, {"t": "单选", "q": "我国“双碳”目标指", "o": ["A.碳达峰、碳中和", "B.碳减排、碳交易", "C.低碳、零碳", "D.低碳、绿色"], "a": "A"}, {"t": "单选", "q": "生态文明建设要牢固树立的思维底线是", "o": ["A.生态红线", "B.耕地红线", "C.城市边界", "D.产业规划"], "a": "A"}]}, {"tier": 3, "topic": "人类命运共同体 / 一带一路", "stat": "开放类 3 题", "reason": "全球治理中国方案，简答论述均出现过。", "q": [{"t": "单选", "q": "构建人类命运共同体，核心要义是建设持久和平、普遍安全、共同繁荣、开放包容、____的世界", "o": ["A.清洁美丽", "B.合作共赢", "C.公平正义", "D.民主自由"], "a": "A"}, {"t": "单选", "q": "“一带一路”倡议的核心理念是", "o": ["A.共商共建共享", "B.互联互通", "C.互利共赢", "D.和平发展"], "a": "A"}, {"t": "单选", "q": "新型国际关系的基本要义是", "o": ["A.相互尊重、公平正义、合作共赢", "B.结盟对抗", "C.零和博弈", "D.大国主导"], "a": "A"}]}, {"tier": 3, "topic": "党的自我革命与全面从严治党", "stat": "党建类 3 题", "reason": "新时代党建核心命题，2026.4 论述考“坚持党的全面领导”。", "q": [{"t": "单选", "q": "新时代党的建设总要求，以党的____为统领", "o": ["A.政治建设", "B.思想建设", "C.组织建设", "D.作风建设"], "a": "A"}, {"t": "单选", "q": "跳出历史周期率的第二个答案是", "o": ["A.自我革命", "B.人民监督", "C.依法治国", "D.从严治党"], "a": "A"}, {"t": "单选", "q": "全面从严治党，基础在全面，关键在严，要害在", "o": ["A.治", "B.管", "C.严", "D.建"], "a": "A"}]}, {"tier": 3, "topic": "“两个结合”的完整表述", "stat": "高频", "reason": "2026.4 简答原题，党的创新理论方法论，选择题同考点高频。", "q": [{"t": "单选", "q": "“两个结合”是指把马克思主义基本原理同____相结合", "o": ["A.中国具体实际、中华优秀传统文化", "B.中国国情、西方经验", "C.中国历史、世界趋势", "D.中国实践、现代科技"], "a": "A"}, {"t": "单选", "q": "“第二个结合”指的是同____相结合", "o": ["A.中华优秀传统文化", "B.中国具体实际", "C.中国基本国情", "D.中国发展实践"], "a": "A"}, {"t": "单选", "q": "“两个结合”是推进马克思主义中国化时代化的", "o": ["A.根本途径", "B.唯一途径", "C.次要方式", "D.理论来源"], "a": "A"}]}, {"tier": 3, "topic": "以人民为中心（共同富裕/民生保障）", "stat": "社会类 4 题 + 高频", "reason": "人民立场是全书价值主线，民生题稳定。", "q": [{"t": "单选", "q": "坚持以人民为中心的发展思想，其核心要义是", "o": ["A.发展为了人民、发展依靠人民、发展成果由人民共享", "B.以经济建设为中心", "C.以人民为发展手段", "D.追求经济增长速度"], "a": "A"}, {"t": "单选", "q": "共同富裕是中国特色社会主义的", "o": ["A.本质要求", "B.最终目标", "C.唯一目标", "D.过渡阶段"], "a": "A"}, {"t": "单选", "q": "保障和改善民生，要抓住人民最关心最直接最现实的", "o": ["A.利益问题", "B.理论问题", "C.发展问题", "D.环境问题"], "a": "A"}]}]}, {"title": "主观题方向（简答/论述，4 套真题已考+教材重点）", "items": [{"tier": 3, "topic": "中国式现代化的中国特色 / 本质要求 / 重大意义", "stat": "简答+论述共 5 次", "reason": "最高频主观题，各角度轮考（本质要求 2025、意义 2024、内涵 2026）。", "q": [{"t": "简答", "q": "简述中国式现代化的五个中国特色", "a": "人口规模巨大的现代化；全体人民共同富裕的现代化；物质文明和精神文明相协调的现代化；人与自然和谐共生的现代化；走和平发展道路的现代化。"}, {"t": "简答", "q": "简述中国式现代化的本质要求", "a": "坚持中国共产党领导，坚持中国特色社会主义，实现高质量发展，发展全过程人民民主，丰富人民精神世界，实现全体人民共同富裕，促进人与自然和谐共生，推动构建人类命运共同体，创造人类文明新形态。"}, {"t": "论述", "q": "试述中国式现代化重大意义（对中国、对世界）", "a": "对中国：是中国共产党领导的社会主义现代化，拓展了发展中国家走向现代化的途径，为中华民族伟大复兴提供了根本遵循；对世界：创造了人类文明新形态，打破了现代化等于西方化的迷思，为人类实现现代化提供了新的选择。"}]}, {"tier": 3, "topic": "如何构建新发展格局", "stat": "2026.4 简答原题", "reason": "高质量发展落地题，双循环+内需+科技自立。", "q": [{"t": "简答", "q": "简述构建新发展格局的核心要义", "a": "以国内大循环为主体、国内国际双循环相互促进；关键在于经济循环的畅通无阻，最本质的特征是实现高水平的自立自强。"}, {"t": "简答", "q": "简述构建新发展格局的主要举措", "a": "加快科技自立自强；增强国内大循环内生动力和可靠性；提升国际循环质量和水平；促进内需和外需、进口和出口协调发展；建设全国统一大市场。"}, {"t": "论述", "q": "试述构建新发展格局的重大意义", "a": "是把握未来发展主动权的战略部署；是应对国际环境深刻变化的必然选择；有利于发挥我国超大规模市场优势；是推动高质量发展的战略基点。"}]}, {"tier": 3, "topic": "中华文明的五个突出特性", "stat": "2026.4 简答原题", "reason": "文化章大题，五个特性背记即可拿分。", "q": [{"t": "简答", "q": "简述中华文明的五个突出特性", "a": "突出的连续性、突出的创新性、突出的统一性、突出的包容性、突出的和平性。"}, {"t": "简答", "q": "简述中华文明突出连续性的意义", "a": "中华文明是世界上唯一没有中断的文明，决定了中华民族必然走自己的路；为坚定文化自信提供了最坚实的历史根基。"}]}, {"tier": 3, "topic": "“两个结合”的完整表述与意义", "stat": "2026.4 简答原题", "reason": "党的理论创新方法论，第二结合是重点。", "q": [{"t": "简答", "q": "简述“两个结合”的完整表述", "a": "把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。"}, {"t": "简答", "q": "简述“第二个结合”的重大意义", "a": "是又一次思想解放；让马克思主义在中国牢牢扎根；巩固了文化主体性；为马克思主义中国化时代化开辟了新境界。"}, {"t": "论述", "q": "试述“两个结合”是推进马克思主义中国化时代化的根本途径", "a": "“两个结合”深刻揭示了马克思主义在中国创新发展的内在机理；同中国具体实际相结合解决中国问题，同中华优秀传统文化相结合赋予马克思主义中国特色；是开辟马克思主义中国化时代化新境界的必由之路。"}]}, {"tier": 2, "topic": "四个全面战略布局（新阶段表述）", "stat": "2025 简答原题", "reason": "战略布局更新后表述易考。", "q": [{"t": "简答", "q": "简述“四个全面”战略布局的内容", "a": "全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党。"}, {"t": "简答", "q": "简述“四个全面”战略布局的内在关系", "a": "全面建设社会主义现代化国家是战略目标；全面深化改革、全面依法治国、全面从严治党是三大战略举措，为战略目标提供动力、法治和政治保证。"}]}, {"tier": 3, "topic": "坚持党的全面领导（最高政治领导力量）", "stat": "2026.4 论述原题", "reason": "全书政治主线大题，材料题高频。", "q": [{"t": "简答", "q": "为什么说中国共产党领导是中国特色社会主义最本质的特征", "a": "党的领导是党和国家的根本所在、命脉所在；决定中国特色社会主义的性质和方向；是中国特色社会主义制度的最大优势；是实现中华民族伟大复兴的根本保证。"}, {"t": "论述", "q": "试述坚持党的全面领导的基本要求", "a": "坚决维护党中央权威和集中统一领导；健全总揽全局、协调各方的党的领导制度体系；提高党把方向、谋大局、定政策、促改革的能力；确保党始终总揽全局、协调各方。"}]}, {"tier": 2, "topic": "人类命运共同体理念的内涵与实践", "stat": "2025 论述原题", "reason": "开放章大题，全球治理方案。", "q": [{"t": "简答", "q": "简述人类命运共同体理念的核心要义", "a": "建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界；各国人民同心协力，共建共享。"}, {"t": "论述", "q": "试述构建人类命运共同体的实践路径", "a": "推动共建“一带一路”高质量发展；积极参与全球治理体系改革和建设；倡导践行真正的多边主义；为应对全球性挑战贡献中国智慧和中国方案。"}]}, {"tier": 2, "topic": "坚持人民立场 / 共同富裕", "stat": "教材重点", "reason": "以人民为中心大题，与民生结合。", "q": [{"t": "简答", "q": "简述坚持人民立场的基本要求", "a": "尊重人民主体地位；保证人民当家作主；发展为了人民、依靠人民、成果由人民共享；始终保持同人民群众的血肉联系。"}, {"t": "论述", "q": "试述扎实推进共同富裕的路径", "a": "坚持高质量发展；完善分配制度，促进机会公平；提高基本公共服务均等化水平；促进农民农村共同富裕；分阶段促进共同富裕，坚持尽力而为、量力而行。"}]}]}]};
